import openpyxl
from openpyxl.worksheet.formula import ArrayFormula
p='3_47360_answer_template_4530_golden.xlsx'
wb=openpyxl.load_workbook(p, data_only=False)
for ws in wb.worksheets:
    print('\n===SHEET', ws.title, ws.max_row, ws.max_column)
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row,35), max_col=ws.max_column):
        vals=[]
        for c in row:
            if c.value is not None:
                v=c.value
                if isinstance(v, ArrayFormula): desc='ARR:'+v.text
                elif isinstance(v,str) and v.startswith('='): desc='F:'+v
                else: desc=repr(v)
                vals.append(f'{c.coordinate}={desc}')
        if vals: print(' | '.join(vals))
